    result = Array.from({length: w}, () => new Array(h).fill(0));
    for (let y = 0; y < w; ++y) {
      for (let x = 0; x < h; ++x) {
        result[y][x] = matrix[h - 1 - x][y];
      }
    }
  } else { // counter-clockwise
    result = Array.from({length: w}, () => new Array(h).fill(0));
    for (let y = 0; y < w; ++y) {
      for (let x = 0; x < h; ++x) {
        result[y][x] = matrix[x][w - 1 - y];
      }
    }
  }
  return result;
}

